CREATE TABLE upload_intents (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, storage_key text NOT NULL UNIQUE, filename text NOT NULL, mime text NOT NULL, expected_size bigint NOT NULL CHECK(expected_size>0), expires_at timestamptz NOT NULL, completed_at timestamptz, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blobs (id uuid PRIMARY KEY, sha256 text NOT NULL, size bigint NOT NULL, storage_key text NOT NULL UNIQUE, mime text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(sha256,size));
CREATE TABLE assets (object_id uuid PRIMARY KEY, workspace_id uuid NOT NULL, blob_id uuid NOT NULL REFERENCES blobs(id), media_type text NOT NULL, state text NOT NULL CHECK(state IN ('processing','ready','failed')), filename text NOT NULL, metadata_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,object_id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX assets_workspace_created_idx ON assets(workspace_id,created_at DESC);
CREATE TABLE asset_variants (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, asset_id uuid NOT NULL REFERENCES assets(object_id) ON DELETE CASCADE, recipe text NOT NULL, blob_id uuid NOT NULL REFERENCES blobs(id), width integer, height integer, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,recipe));
CREATE TABLE asset_usages (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, asset_id uuid NOT NULL REFERENCES assets(object_id) ON DELETE CASCADE, owner_object_id uuid NOT NULL, role text NOT NULL, locator_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,owner_object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX asset_usages_owner_idx ON asset_usages(workspace_id,owner_object_id);
